const readline = require('readline');
const rl = readline.createInterface({ input: process.stdin, output: process.stdout });

rl.on('line', (s) => {
    let shifts = new Set();
    let n = s.length;
    for (let i = 0; i < n; i++) {
        let shifted = s.slice(i) + s.slice(0, i);
        shifts.add(shifted);
    }
    console.log(shifts.size);
    rl.close();
});
```

